  'xt.song.notfound': { en: "couldn't find it on Spotify", 'zh-Hant': '在 Spotify 上找不到這首歌', 'zh-Hans': '在 Spotify 上找不到这首歌', ja: 'Spotify で見つかりませんでした', ko: 'Spotify에서 찾을 수 없습니다' },
  'xd.stop':      { en: 'STOP', 'zh-Hant': '停止', 'zh-Hans': '停止', ja: '停止', ko: '중지' },
  'xd.stop.hint': { en: 'Stop after the current clip — the one already at the provider finishes and is billed; every scene not yet started stays a draft.', 'zh-Hant': '目前這支跑完就停 — 已送出供應商的這支會完成並計費；尚未開始的鏡頭全部保留為草稿。', 'zh-Hans': '当前这支跑完就停 — 已送出供应商的这支会完成并计费；尚未开始的镜头全部保留为草稿。', ja: '現在のクリップ完了後に停止 — プロバイダ送信済みの分は完了し課金されます。未開始のシーンはドラフトのまま。', ko: '현재 클립 완료 후 중지 — 이미 전송된 클립은 완료되어 과금됩니다. 시작 전 장면은 초안으로 유지.' },
  'xd.stopped':   { en: '⏹ Stopped — the remaining scenes stay as drafts. Press ▶ when you want to continue.', 'zh-Hant': '⏹ 已停止 — 其餘鏡頭保留為草稿，要繼續時再按 ▶。', 'zh-Hans': '⏹ 已停止 — 其余镜头保留为草稿，要继续时再按 ▶。', ja: '⏹ 停止しました — 残りのシーンはドラフトのまま。続けるときは ▶ を。', ko: '⏹ 중지됨 — 남은 장면은 초안으로 유지됩니다. 계속하려면 ▶.', },
  'xd.sb.nospeech':     { en: 'NO SPEECH', 'zh-Hant': '不說話', 'zh-Hans': '不说话', ja: '発話なし', ko: '무발화' },
  'xd.sb.nospeech.on':  { en: 'Performance only: the cast acts but never sings, speaks or mouths words — mix your own audio later. Click to allow speaking shots.', 'zh-Hant': '純表演：演員只演，不唱不說不動嘴 — 音訊之後自行混。點擊改為允許說話鏡頭。', 'zh-Hans': '纯表演：演员只演，不唱不说不动嘴 — 音频之后自行混。点击改为允许说话镜头。', ja: '演技のみ：歌唱・発話・口パクなし — 音声は後でミックス。クリックで発話ショットを許可。', ko: '연기만: 노래·발화·입모양 없음 — 오디오는 나중에 믹스. 클릭하면 발화 샷 허용.' },
  'xd.sb.nospeech.off': { en: 'Speaking shots allowed. There is no lip-sync here, so any mouth movement is invented and follows the prompt language, not the song. Click for performance-only.', 'zh-Hant': '允許說話鏡頭。本站沒有對嘴功能，嘴型是模型自行編造、且跟著提示詞語言而非歌曲。點擊改為純表演。', 'zh-Hans': '允许说话镜头。本站没有对嘴功能，嘴型是模型自行编造、且跟着提示词语言而非歌曲。点击改为纯表演。', ja: '発話ショットを許可。リップシンクは無く、口の動きはモデルの創作でプロンプトの言語に従います。クリックで演技のみに。', ko: '발화 샷 허용. 립싱크가 없어 입 움직임은 모델이 지어내며 프롬프트 언어를 따릅니다. 클릭하면 연기 전용.' },
  'xd.sb.mode.keyframe': { en: 'KEYFRAME', 'zh-Hant': '關鍵幀', 'zh-Hans': '关键帧', ja: 'キーフレーム', ko: '키프레임' },
  'xd.sb.mode.direct':   { en: 'DIRECT', 'zh-Hant': '直出', 'zh-Hans': '直出', ja: 'ダイレクト', ko: '다이렉트' },
  'xd.sb.mode.keyframe.hint': { en: 'KEYFRAME: shoot a cheap key still, approve the look, then animate from that exact frame. Click to switch this cut to DIRECT.', 'zh-Hant': '關鍵幀模式：先產生便宜的關鍵幀，確認畫面後再以該幀生成影片。點擊切換為直出。', 'zh-Hans': '关键帧模式：先生成便宜的关键帧，确认画面后再以该帧生成视频。点击切换为直出。', ja: 'キーフレーム：安価な静止画で画作りを確認してから、そのフレームから動画化。クリックでダイレクトに切替。', ko: '키프레임: 저렴한 스틸로 룩을 확정한 뒤 그 프레임에서 영상 생성. 클릭하면 다이렉트로 전환.' },
  'xd.sb.mode.direct.hint':   { en: 'DIRECT: straight to video, no still — faster and one bill, but the look is only settled once the clip is paid for. Click to switch this cut to KEYFRAME.', 'zh-Hant': '直出模式：不產生關鍵幀，直接生成影片 — 較快、只付一次，但畫面要等影片出來才知道。點擊切換為關鍵幀。', 'zh-Hans': '直出模式：不生成关键帧，直接生成视频 — 较快、只付一次，但画面要等视频出来才知道。点击切换为关键帧。', ja: 'ダイレクト：静止画なしで直接動画へ — 速く支払いも一度だが、画は動画が出るまで確定しない。クリックでキーフレームに切替。', ko: '다이렉트: 스틸 없이 바로 영상 — 빠르고 한 번만 결제하지만, 룩은 클립이 나와야 확정됨. 클릭하면 키프레임으로 전환.' },
  'xd.sb.skipstill':   { en: 'Skip the still — shoot this cut straight to video', 'zh-Hant': '跳過關鍵幀 — 這顆鏡頭直接出影片', 'zh-Hans': '跳过关键帧 — 这颗镜头直接出视频', ja: 'キーフレームを省略 — このカットは直接動画へ', ko: '스틸 건너뛰기 — 이 컷은 바로 영상으로' },
